package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen0Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }



    @Test
    public void testRemoveColumn_ExistingColumnWithValues() {
        // Setup data
        Comparable rowKey1 = "Row1";
        Comparable rowKey2 = "Row2";
        Comparable colKey1 = "Col1";
        Comparable colKey2 = "Col2";

        dataset.addValue(10.0, rowKey1, colKey1);
        dataset.addValue(20.0, rowKey1, colKey2);
        dataset.addValue(30.0, rowKey2, colKey1);
        dataset.addValue(40.0, rowKey2, colKey2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals(10.0, dataset.getValue(rowKey1, colKey1).doubleValue(), 0.001);

        // Execute
        dataset.removeColumn(colKey1);

        // Verify column is removed from column keys
        assertEquals(1, dataset.getColumnCount());
        assertFalse(dataset.getColumnKeys().contains(colKey1));
        assertTrue(dataset.getColumnKeys().contains(colKey2));

        // Verify values associated with colKey1 are removed from rows
        assertNull(dataset.getValue(rowKey1, colKey1));
        assertNull(dataset.getValue(rowKey2, colKey1));

        // Verify other values remain
        assertEquals(20.0, dataset.getValue(rowKey1, colKey2).doubleValue(), 0.001);
        assertEquals(40.0, dataset.getValue(rowKey2, colKey2).doubleValue(), 0.001);
    }






}

